/// Cell id for an emoji token (variation selector U+FE0F stripped).
pub fn emoji_to_cell(token: &str) -> Option<u8> {
    Some(match token.trim_end_matches('\u{FE0F}') {
        "⬛" => 0,  // space
        "🟫" => 2,  // mud
        "⬜" => 3,  // steel wall
        "🚪" => 4,  // door (spawn + exit)
        "🧱" => 5,  // brick wall
        "✨" => 6,  // magic wall
        "🪨" => 7,  // boulder
        "💎" => 8,  // diamond
        "🐝" => 0xB, // firefly-class enemy
        "🦋" => 0xC, // butterfly-class enemy
        "🦠" => 0xD, // amoeba
        _ => return None,
    })
}

/// Parse an emoji cave file into a 40x22 grid (row-major, index = y*40+x).
/// Lines starting with `#` are comments. Returns None on unknown tokens
/// or a cell count other than 880.
pub fn parse_cave(text: &str) -> Option<[u8; 880]> {
    let mut cells = [0u8; 880];
    let mut n = 0;
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        for tok in line.split_whitespace() {
            if n >= 880 {
                return None;
            }
            cells[n] = emoji_to_cell(tok)?;
            n += 1;
        }
    }
    (n == 880).then_some(cells)
}
